import{c as e,Q as a,j as s,m as i}from"./chunks/framework.7r1mYKiJ.js";const g=JSON.parse('{"title":"Database Setup","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/database.md","filePath":"getting-started/database.md"}'),n={name:"getting-started/database.md"};function o(l,t,r,d,h,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="database-setup" tabindex="-1">Database Setup <a class="header-anchor" href="#database-setup" aria-label="Permalink to &quot;Database Setup&quot;">​</a></h1><p>AetherUHC requires a database to store player statistics, match history, scenario preferences, and team records. Two database backends are supported:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Backend</th><th style="text-align:left;">Best For</th><th style="text-align:left;">Setup Required</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SQLite</strong> <em>(default)</em></td><td style="text-align:left;">Single servers, local testing</td><td style="text-align:left;">None</td></tr><tr><td style="text-align:left;"><strong>MongoDB</strong></td><td style="text-align:left;">Multi-server networks with shared stats</td><td style="text-align:left;">Yes</td></tr></tbody></table><hr><h2 id="sqlite-default-—-zero-configuration" tabindex="-1">SQLite (Default — Zero Configuration) <a class="header-anchor" href="#sqlite-default-—-zero-configuration" aria-label="Permalink to &quot;SQLite (Default — Zero Configuration)&quot;">​</a></h2><p>SQLite is enabled automatically when MongoDB is not configured. No additional software or credentials are required. AetherUHC will create a file called <code>aetheruhc.db</code> inside <code>plugins/AetherUHC/</code> on first boot.</p><p>Data stored per-player:</p><ul><li>Kill count, death count, wins</li><li>All-time KDR</li><li>Match participation history</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>SQLite data is local to the server it runs on. If you run multiple UHC servers on the same network, each server will have its own separate player database. Use MongoDB if you need unified stats across all servers.</p></div><hr><h2 id="mongodb-recommended-for-networks" tabindex="-1">MongoDB (Recommended for Networks) <a class="header-anchor" href="#mongodb-recommended-for-networks" aria-label="Permalink to &quot;MongoDB (Recommended for Networks)&quot;">​</a></h2><p>MongoDB allows multiple AetherUHC servers to share the <strong>same database</strong>, enabling global leaderboards, cross-server stats, and unified player records.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>A running MongoDB instance (local or hosted via MongoDB Atlas, etc.)</li><li>A database user with read/write access to the target database</li></ul><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><p>Open <code>plugins/AetherUHC/settings.yml</code> and locate the <code>MONGO</code> section:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">MONGO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  URI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mongodb://user:password@localhost:27017/admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AetherUHC&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ENABLED</code></td><td style="text-align:left;">Set to <code>true</code> to activate MongoDB (disables SQLite)</td></tr><tr><td style="text-align:left;"><code>URI</code></td><td style="text-align:left;">Your full MongoDB connection string</td></tr><tr><td style="text-align:left;"><code>DATABASE</code></td><td style="text-align:left;">The name of the database to store AetherUHC collections in</td></tr></tbody></table><p>After editing, restart the server. AetherUHC will create the required collections automatically on first boot.</p><h3 id="connection-string-examples" tabindex="-1">Connection String Examples <a class="header-anchor" href="#connection-string-examples" aria-label="Permalink to &quot;Connection String Examples&quot;">​</a></h3><p><strong>Local MongoDB (no auth):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb://localhost:27017</span></span></code></pre></div><p><strong>Local MongoDB (with auth):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb://myUser:myPassword@localhost:27017/admin</span></span></code></pre></div><p><strong>MongoDB Atlas (cloud-hosted):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mongodb+srv://myUser:myPassword@cluster0.mongodb.net/AetherUHC?retryWrites=true&amp;w=majority</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If your MongoDB server is externally hosted, ensure your Minecraft server&#39;s IP address is whitelisted in the MongoDB firewall / Atlas Network Access settings. Connection timeouts are almost always caused by missing IP whitelisting.</p></div><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Never commit your MongoDB URI (with password) to a public repository. Use environment variables or keep <code>settings.yml</code> in your <code>.gitignore</code>.</p></div><hr><h2 id="mariadb-mysql-alternative" tabindex="-1">MariaDB / MySQL (Alternative) <a class="header-anchor" href="#mariadb-mysql-alternative" aria-label="Permalink to &quot;MariaDB / MySQL (Alternative)&quot;">​</a></h2><p>AetherUHC also supports relational database backends via HikariCP. To use MariaDB or MySQL:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">SQL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;localhost&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  PORT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3306</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  DATABASE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aetheruhc&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  USERNAME</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uhcuser&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  PASSWORD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;yourpassword&quot;</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>If both <code>MONGO.ENABLED</code> and <code>SQL.ENABLED</code> are true, MongoDB takes priority.</p></div><hr><h2 id="verifying-the-connection" tabindex="-1">Verifying the Connection <a class="header-anchor" href="#verifying-the-connection" aria-label="Permalink to &quot;Verifying the Connection&quot;">​</a></h2><p>After restarting with the database configured, check <code>logs/latest.log</code> for the following line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[AetherUHC] Database connected successfully. (MongoDB | AetherUHC)</span></span></code></pre></div><p>If you instead see a connection error, double-check your URI, credentials, and that the database server is reachable from the Minecraft host.</p><hr><h2 id="migrating-from-sqlite-to-mongodb" tabindex="-1">Migrating from SQLite to MongoDB <a class="header-anchor" href="#migrating-from-sqlite-to-mongodb" aria-label="Permalink to &quot;Migrating from SQLite to MongoDB&quot;">​</a></h2><p>If you started with SQLite and want to move to MongoDB:</p><ol><li>Stop the server.</li><li>Enable MongoDB in <code>settings.yml</code>.</li><li>Restart the server. Players will start accumulating stats in MongoDB from this point forward.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Historical SQLite data is not automatically migrated. If you need to preserve historical player records, a manual migration script will be required.</p></div>`,43)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
